cd /var/folders/5p/0d4szgs13t5b74h2c379j3gc0000gn/T/opencode/pathland-design && cat > probe2.js <<'EOF'
const g = figma.graph;
const out = {};
out.sigs = {
  resolveVariable: g.resolveVariable.toString().slice(0,300),
  resolveColorVariable: g.resolveColorVariable.toString().slice(0,300),
  resolveColorVariableForNode: g.resolveColorVariableForNode.toString().slice(0,300),
  getNodeVariableModeId: g.getNodeVariableModeId.toString().slice(0,300),
  updateNode: g.updateNode.toString().slice(0,400),
};
const page = g.getPages()[0];
const c = g.createCollection('ZZ Probe');
const light = c.modes[0].modeId;
g.renameMode(c.id, light, 'Light');
const dark = g.createMode(c.id, 'Dark');
const base = g.createVariable('zz.base', 'COLOR', c.id, { r: 1, g: 0, b: 0, a: 1 });
base.valuesByMode[dark] = { r: 0, g: 0, b: 1, a: 1 };
let sem;
try {
  sem = g.createVariable('zz.sem', 'COLOR', c.id, { type: 'VARIABLE_ALIAS', id: base.id });
  sem.valuesByMode[dark] = { type: 'VARIABLE_ALIAS', id: base.id };
  out.aliasCreate = 'ok';
} catch (e) { out.aliasCreate = String(e); }
out.aliasStored = sem ? sem.valuesByMode : null;
try { out.resolveSemLight = g.resolveColorVariable(sem.id, light); } catch (e) { out.resolveSemLight = String(e); }
try { out.resolveSemDark = g.resolveColorVariable(sem.id, dark); } catch (e) { out.resolveSemDark = String(e); }
const frame = g.createNode('FRAME', page.id, { name: 'zz.frame', x: -900, y: -900, width: 10, height: 10, fills: [{ type: 'SOLID', color: { r: 0, g: 0, b: 0, a: 1 }, opacity: 1, visible: true }] });
try { g.bindVariable(frame.id, 'fills/0/color', sem.id); out.bound = g.getNode(frame.id).boundVariables; } catch (e) { out.bindErr = String(e); }
try { out.resolvedNodeLight = g.resolveColorVariableForNode(frame.id, 'fills/0/color'); } catch (e) { out.resolvedNodeLight = String(e); }
try { g.updateNode(frame.id, { variableModes: { [c.id]: dark } }); out.nodeModes = g.getNode(frame.id).variableModes; out.modeIdDark = g.getNodeVariableModeId(frame.id, c.id); } catch (e) { out.modeErr = String(e); }
try { out.resolvedNodeDark = g.resolveColorVariableForNode(frame.id, 'fills/0/color'); } catch (e) { out.resolvedNodeDark = String(e); }
try { g.deleteNode(frame.id); } catch (e) {}
try { g.removeCollection(c.id); } catch (e) {}
return out;
EOF
