  const focus = g.getNode(set.childIds.find(id => g.getNode(id).name === 'State=Focus'));
  setStrokes(focus.id, [solid('#2563eb', 2, 'OUTSIDE')]);
  bind(focus.id, 'strokes/0/color', 'toggle.accent');
  out.push({ node: 'Switch Focus light', id: focus.id });
}
