  const thumb = g.getNode(track.childIds.find(id => g.getNode(id).name === 'Thumb'));
  setStrokes(thumb.id, [solid('#ffffff', 1, 'INSIDE'), solid('#2563eb', 2, 'OUTSIDE')]);
  bind(thumb.id, 'strokes/0/color', 'slider.thumb');
  bind(thumb.id, 'strokes/1/color', 'slider.accent');
  out.push({ node: 'Slider Focus thumb light', id: thumb.id });
}
