const g = figma.graph;
const byName = new Map(); for (const v of g.variables.values()) byName.set(v.name, v);
function bind(n, field, token) {
  const v = byName.get(token); if (!v) return 'missing ' + token;
  if (n.boundVariables && n.boundVariables[field]) return 'bound';
  try { g.bindVariable(n.id, field, v.id); return 'ok'; } catch (e) { return String(e); }
}
function anc(n){const a=[];let p=n,d=0;while(p&&d++<35){a.push(p);p=p.parentId?g.getNode(p.parentId):null;}return a;}
function inInst(n){return anc(n).some(p=>p.type==='INSTANCE');}
const stats={chipFill:0,chipText:0,icon:0,errors:[]};

// base palette chips + labels
for(const item of [...g.nodes.values()]){
  if(item.type!=='FRAME'||!/^base /.test(item.name||''))continue;
  const token='base.color.'+item.name.slice(5);
  const kids=item.childIds.map(id=>g.getNode(id));
  const chip=kids.find(c=>c.type==='FRAME'&&c.name==='Chip');
  if(chip){const r=bind(chip,'fills/0/color',token); if(r==='ok')stats.chipFill++; else if(r!=='bound')stats.errors.push({id:chip.id,token,r});}
  for(const t of kids.filter(c=>c.type==='TEXT')){const r=bind(t,'fills/0/color','color.text.secondary'); if(r==='ok')stats.chipText++; else if(r!=='bound')stats.errors.push({id:t.id,token:'color.text.secondary',r});}
}

// icon vectors
const ICON_TOKENS={
  Button:'control.foreground', Select:'color.text.secondary', Date:'color.text.secondary',
  Checkbox:'base.color.white', Spinner:'color.accent', Stepper:'color.accent',
  Media:'color.primary', Icon:'color.text.primary',
};
for(const n of [...g.nodes.values()]){
  if(n.type!=='VECTOR'||inInst(n))continue;
  const a=anc(n);
  const set=a.find(p=>p.type==='COMPONENT_SET');
  const comp=a.find(p=>p.type==='COMPONENT');
  const raw=set?set.name:(comp?comp.name:'');
  const base=raw.replace(/ Dark$/,'');
  const token=ICON_TOKENS[base];
  if(!token)continue;
  const b=n.boundVariables||{};
  (n.strokes||[]).forEach((s,i)=>{if(s.type==='SOLID'&&!b['strokes/'+i+'/color']){const r=bind(n,'strokes/'+i+'/color',token); if(r==='ok')stats.icon++; else if(r!=='bound')stats.errors.push({id:n.id,token,r});}});
  (n.fills||[]).forEach((f,i)=>{if(f.type==='SOLID'&&!b['fills/'+i+'/color']){const r=bind(n,'fills/'+i+'/color',token); if(r==='ok')stats.icon++; else if(r!=='bound')stats.errors.push({id:n.id,token,r});}});
}
return stats;
EOF
