input.content:
import fs from 'node:fs';
import path from 'node:path';

for (const dir of ['Base', 'Semantic', 'Component']) {
  const d = '/tmp/pl-dtcg-final/' + dir;
  for (const f of fs.readdirSync(d)) {
    const o = JSON.parse(fs.readFileSync(path.join(d, f), 'utf8'));
    console.log(`${dir}/${f}: ${Object.keys(o).length} tokens`);
  }
}
const sem = JSON.parse(fs.readFileSync('/tmp/pl-dtcg-final/Semantic/Light.tokens.json', 'utf8'));
const byName = new Map(Object.entries(sem).map(([k, v]) => [v.$extensions?.dev?.openpencil?.name, v]));
const ty = [...byName.keys()].filter((n) => n && /^font\./.test(n)).sort();
console.log('\nsemantic font tokens:', ty);
for (const n of ['font.body.lineHeight', 'font.caption.size', 'font.meta.weight', 'font.heading.1.family', 'font.heading.2.lineHeight']) {
  console.log(n, JSON.stringify(byName.get(n)));
}
const base = JSON.parse(fs.readFileSync('/tmp/pl-dtcg-final/Base/Value.tokens.json', 'utf8'));
const baseByName = new Map(Object.entries(base).map(([k, v]) => [v.$extensions?.dev?.openpencil?.name, v]));
for (const n of ['base.font.size.12', 'base.font.line-height.24', 'base.font.letter-spacing.0_56', 'base.font.family.inter', 'base.radius.2xl']) {
  console.log(n, JSON.stringify(baseByName.get(n)));
}
const hasAlias = (obj) => JSON.stringify(obj).includes('"$ref"') || JSON.stringify(obj).includes('VARIABLE_ALIAS');
const comp = JSON.parse(fs.readFileSync('/tmp/pl-dtcg-final/Component/Light.tokens.json', 'utf8'));
console.log('\nalias-like refs?', hasAlias(comp), hasAlias(sem));
const semDark = JSON.parse(fs.readFileSync('/tmp/pl-dtcg-final/Semantic/Dark.tokens.json', 'utf8'));
console.log('dark control.background', JSON.stringify(Object.entries(semDark).find(([k, v]) => v.$extensions?.dev?.openpencil?.name === 'control.background')?.[1]));

